create function pg_temp.capacity_details(statement text) returns jsonb language plpgsql as $test$
declare details text;
begin
  execute statement;
  return null;
exception when check_violation then get stacked diagnostics details=pg_exception_detail; return details::jsonb;
end;
$test$;
select set_config('request.jwt.claim.sub','71000000-0000-4000-8000-000000000001',true);
set local role authenticated;
