select throws_ok($$update events set max_capacity=3 where id='72000000-0000-4000-8000-000000000005'$$,'23514','capacity violation','US2 assigned 6 rejects aforo 3 with consumption 3');
select is((select max_capacity from events where id='72000000-0000-4000-8000-000000000005'),6,'US2 assigned-capacity rejection rolls back');
select throws_ok($$select update_event_configuration('{"eventId":"72000000-0000-4000-8000-000000000006","event":{"title":"Must rollback","maxCapacity":3},"ticketType":{"id":"73000000-0000-4000-8000-000000000062","maxCapacity":1}}')$$,'23514','capacity violation','US3 combined request rejects all three violations');
