select is((pg_temp.capacity_details($$select update_event_configuration('{"eventId":"72000000-0000-4000-8000-000000000006","event":{"maxCapacity":3},"ticketType":{"id":"73000000-0000-4000-8000-000000000062","maxCapacity":1}}')$$)->'violations'->2->>'minimumCapacity')::integer,6,'combined DETAIL distinguishes final assignment 6');
